const BY_CODE = new Map(MARKETS.map((m) => [m.code, m]));

export const SOURCE = 'synthetic';
export const DISCLAIMER = 'Simulated prices generated by NovaTrade KE for practice. Not live market data.';

export const findMarket = (code) => BY_CODE.get(code) || BY_CODE.get(String(code || '').toUpperCase()) || null;

/** Symbol descriptors for the API (no internal fields beyond what a client needs). */
export function symbolList() {
  const nowMs = Date.now();
  return MARKETS.map((m) => {
    const q = quoteAt(m.code, nowMs);
    const prev = quoteAt(m.code, nowMs - 24 * 3600 * 1000);
    return {
      code: m.code,
      name: m.name,
      group: m.group,
      digits: m.digits,
      pipSize: Math.pow(10, -m.digits),
      tickMs: TICK_MS,
      last: q.quote,
      bid: q.bid,
      ask: q.ask,
      changePct: prev && prev.quote ? Number((((q.quote - prev.quote) / prev.quote) * 100).toFixed(3)) : 0,
    };
  });
}

function phaseOf(code) {
  // Distinct phase so no two markets move together.
  return rand01(fnv1a(`${code}|phase`)) * 3600;
}

function roundTo(value, digits) {
  const f = Math.pow(10, digits);
  return Math.round(value * f) / f;
}

/** The price of `code` at `epochMs`. Pure, deterministic and safe to call from anywhere. */
export function quoteAt(code, epochMs = Date.now()) {
  const m = findMarket(code);
  if (!m) return null;
  const t = epochMs / 1000;
  const phase = phaseOf(m.code);
  let n = 0;
  for (let i = 0; i < OCTAVES.length; i++) {
    n += OCTAVES[i].amp * noise(`${m.code}|${i}`, (t + phase) / OCTAVES[i].period);
  }
  // A slow trend so a chart has structure instead of sounding like static.
  const drift = 0.5 * Math.sin((t + phase) / 5400) + 0.25 * Math.sin((t + phase) / 28800);
  const price = m.base * (1 + m.vol * (n + drift));
  const half = (m.spreadBp / 10000) * price / 2;
  return {
    code: m.code,
    epoch: epochMs,
    quote: roundTo(price, m.digits),
    bid: roundTo(price - half, m.digits),
    ask: roundTo(price + half, m.digits),
  };
}

/** The tick grid: the moment the tick covering `epochMs` was published. */
export const tickEpoch = (epochMs = Date.now()) => Math.floor(epochMs / TICK_MS) * TICK_MS;

/** The most recent `count` ticks, oldest first, ending at the current tick. */
export function ticks(code, count = 60) {
  const m = findMarket(code);
  if (!m) return null;
  const n = Math.max(1, Math.min(1000, Number(count) || 60));
  const end = tickEpoch();
  const out = [];
  for (let i = n - 1; i >= 0; i--) {
    const epoch = end - i * TICK_MS;
    out.push({ epoch, quote: quoteAt(m.code, epoch).quote });
  }
  return { code: m.code, tickMs: TICK_MS, ticks: out };
}

/** OHLC candles of `granularity` seconds each, oldest first. */
export function candles(code, granularity = 60, count = 60) {
  const m = findMarket(code);
  if (!m) return null;
  const g = Math.max(30, Math.min(3600, Number(granularity) || 60));
  const n = Math.max(1, Math.min(500, Number(count) || 60));
  const nowTick = tickEpoch();
  const end = Math.floor(nowTick / (g * 1000)) * g * 1000; // start of the current bucket
  const out = [];
  for (let i = n; i >= 1; i--) {
    const start = end - i * g * 1000;
    let open = null; let high = -Infinity; let low = Infinity; let close = null;
    for (let epoch = start; epoch < start + g * 1000; epoch += TICK_MS) {
      if (epoch > nowTick) break;
      const q = quoteAt(m.code, epoch).quote;
      if (open === null) open = q;
      high = Math.max(high, q);
      low = Math.min(low, q);
      close = q;
    }
    if (open === null) continue;
    out.push({ epoch: start, open, high, low, close });
  }
  return { code: m.code, granularity: g, candles: out };
}
